 v_packet jsonb := $pkt${"checkpoint":"A7Q_C3","checks":[{"code":"COVERAGE_COMPLETE","statement":"Cada requirement_id y cada 'dimension:<nombre>' de la entrada queda vinculado a al menos un frente; no se inventan frentes que la entrada no sustente."},{"code":"NO_NA_REUSE_WITHOUT_EVIDENCE","statement":"No hay frentes NOT_APPLICABLE ni REUSE_AS_IS: la entrada no trae autoridad positiva ni evidencia de vigencia que los respalde."},{"code":"BLOCKED_FRONTS_VALID","statement":"Todo frente está BLOCKED y sus blockers son decision_id que existen en la entrada; las referencias son válidas y no se propone solución técnica."}],"criterion":"Juez comprueba cobertura, evidencias de NA/REUSE y frentes BLOCKED","decision_doc":"docs/programming-agent/ANALYSIS_C3_TIER_ACCEPTANCE_DECISION_V1.md","evidence_tier":"OWNER_APPROVED_GPT_NATIVE_IN_CHAT_EQUIVALENT","input":{"input_literal":"{\n  \"a6_stage_output\": {\n    \"dimensions\": {\n      \"data\": {\n        \"blocked_by\": [\n          \"A5-DEC-002\",\n          \"A5-DEC-004\"\n        ],\n        \"note\": \"Se identifican como conceptos materiales el ahorro y el monto de la cuota. No están autorizadas sus definiciones, valores, bases de comparación ni relaciones. No se presuponen importes ni reglas de cálculo.\",\n        \"status\": \"PROVISIONAL_PENDING_DECISION\"\n      },\n      \"errors\": {\n        \"blocked_by\": [\n          \"A5-DEC-002\",\n          \"A5-DEC-003\"\n        ],\n        \"note\": \"No se suministran comportamientos autorizados frente a información de ahorro no disponible, indeterminada o incompatible con las condiciones de la oferta. No se establecen resultados de error sin evidencia.\",\n        \"status\": \"BLOCKED_UNDETERMINED\"\n      },\n      \"functional\": {\n        \"blocked_by\": [\n          \"A5-DEC-001\",\n          \"A5-DEC-002\",\n          \"A5-DEC-003\",\n          \"A5-DEC-004\"\n        ],\n        \"note\": \"Se identifican las obligaciones funcionales de comunicar el ahorro antes de aceptar una oferta y distinguirlo de la cuota. Su alcance, significado y condiciones permanecen pendientes de decisión.\",\n        \"status\": \"PROVISIONAL_PENDING_DECISION\"\n      },\n      \"permissions\": {\n        \"blocked_by\": [\n          \"A5-DEC-001\"\n        ],\n        \"note\": \"La entrada no proporciona evidencia de permisos, roles autorizados ni reglas de acceso. No se establecen permisos por inferencia.\",\n        \"status\": \"BLOCKED_UNDETERMINED\"\n      },\n      \"side_effects\": {\n        \"blocked_by\": [\n          \"A5-DEC-003\",\n          \"A5-DEC-004\"\n        ],\n        \"note\": \"No se conocen efectos colaterales autorizados asociados a comunicar el ahorro, distinguir cuotas o aceptar ofertas. No se afirma que existan ni que estén ausentes.\",\n        \"status\": \"BLOCKED_UNDETERMINED\"\n      },\n      \"state\": {\n        \"blocked_by\": [\n          \"A5-DEC-003\"\n        ],\n        \"note\": \"No existe evidencia suficiente sobre los estados de la oferta, sus transiciones o las condiciones que habilitan comunicar el ahorro. No se inventan estados.\",\n        \"status\": \"BLOCKED_UNDETERMINED\"\n      }\n    },\n    \"evidence_refs\": [\n      \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\",\n      \"supabase://public.lf_eventos/20843\",\n      \"gap:TARGET_AUTHORITY_NOT_SUPPLIED\",\n      \"gap:SAVINGS_SEMANTICS_UNRESOLVED\",\n      \"gap:OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n      \"gap:INSTALLMENT_DISTINCTION_UNRESOLVED\",\n      \"gap:ACCEPTANCE_EVIDENCE_MISSING\",\n      \"decision:A5-DEC-001\",\n      \"decision:A5-DEC-002\",\n      \"decision:A5-DEC-003\",\n      \"decision:A5-DEC-004\",\n      \"decision:A5-DEC-005\"\n    ],\n    \"no_unlicensed_how\": true,\n    \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n    \"requirements\": [\n      {\n        \"depends_on_decisions\": [\n          \"A5-DEC-001\",\n          \"A5-DEC-003\"\n        ],\n        \"requirement_id\": \"A6-REQ-001\",\n        \"source_ref\": \"decision:A5-DEC-001\",\n        \"statement\": \"Los clientes comprendidos en el alcance autorizado del piloto deberán poder conocer el ahorro asociado a la negociación de su deuda antes de aceptar una oferta, conforme a las condiciones funcionales que se determinen.\",\n        \"status\": \"PROVISIONAL_PENDING_DECISION\",\n        \"type\": \"FUNCTIONAL\"\n      },\n      {\n        \"depends_on_decisions\": [\n          \"A5-DEC-002\"\n        ],\n        \"requirement_id\": \"A6-REQ-002\",\n        \"source_ref\": \"decision:A5-DEC-002\",\n        \"statement\": \"La información del ahorro deberá corresponder a una definición y una base de comparación autorizadas, todavía pendientes de determinar.\",\n        \"status\": \"PROVISIONAL_PENDING_DECISION\",\n        \"type\": \"DATA\"\n      },\n      {\n        \"depends_on_decisions\": [\n          \"A5-DEC-003\"\n        ],\n        \"requirement_id\": \"A6-REQ-003\",\n        \"source_ref\": \"decision:A5-DEC-003\",\n        \"statement\": \"La disponibilidad de la información del ahorro deberá respetar el momento y las condiciones autorizadas de la oferta antes de su aceptación.\",\n        \"status\": \"PROVISIONAL_PENDING_DECISION\",\n        \"type\": \"FUNCTIONAL\"\n      },\n      {\n        \"depends_on_decisions\": [\n          \"A5-DEC-002\",\n          \"A5-DEC-004\"\n        ],\n        \"requirement_id\": \"A6-REQ-004\",\n        \"source_ref\": \"decision:A5-DEC-004\",\n        \"statement\": \"La información comunicada al cliente deberá permitir distinguir el ahorro de la negociación del monto de la cuota, conforme a las definiciones funcionales que resulten autorizadas.\",\n        \"status\": \"PROVISIONAL_PENDING_DECISION\",\n        \"type\": \"FUNCTIONAL\"\n      },\n      {\n        \"depends_on_decisions\": [\n          \"A5-DEC-004\",\n          \"A5-DEC-005\"\n        ],\n        \"requirement_id\": \"A6-REQ-005\",\n        \"source_ref\": \"decision:A5-DEC-005\",\n        \"statement\": \"La claridad de la información sobre ahorro y cuota deberá poder evaluarse mediante criterios de comprensión y aceptación previamente autorizados para el piloto.\",\n        \"status\": \"PROVISIONAL_PENDING_DECISION\",\n        \"type\": \"NON_FUNCTIONAL\"\n      }\n    ],\n    \"requirements_statement\": \"Se formularon cinco requisitos provisionales, de naturaleza funcional, de datos y no funcional, vinculados a las cinco decisiones pendientes de A5. Ninguno constituye una obligación aprobada ni una autorización de implementación. Las dimensiones funcional y de datos contienen únicamente necesidades condicionadas. Permisos, estados, errores y efectos colaterales permanecen BLOCKED_UNDETERMINED por falta de evidencia. También están pendientes la verificación de autoridad vigente, la identificación de la implementación existente y la línea base AS-IS. El resultado expresa exclusivamente QUÉ se necesita definir y cumplir, sin seleccionar tecnología, diseño, estructuras internas, reglas económicas no autorizadas ni decisiones de producto.\",\n    \"schema_version\": \"A6_REQUIREMENTS_OUTPUT_V1\"\n  }\n}","input_origin":"A6Q_C2 GPT Native RAW (raw_output_sha256 e6ceef2605a44a7f63837784089cf3c8f40f7a3500d20f2a07adfc63c5cfac29)","input_sha256":"0123c9036da30d1235033b8d3c9ac3507f528ea2b36c2da93b97e5085094971b","request_ref":"REQ-LF-A1Q-C2-PILOT-0001"},"items":[{"item_id":"ITEM_A","text":"{\n  \"schema_version\": \"A7_FRONTS_OUTPUT_V1\",\n  \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n  \"material_fronts\": [\n    {\n      \"front_id\": \"A7-FRONT-001\",\n      \"scope_ids\": [\n        \"A6-REQ-001\",\n        \"dimension:functional\",\n        \"dimension:permissions\"\n      ],\n      \"obligation_mode\": \"REQUIRED\",\n      \"closure\": \"BLOCKED\",\n      \"blockers\": [\n        \"A5-DEC-001\",\n        \"A5-DEC-003\"\n      ],\n      \"evidence_refs\": [\n        \"A6-REQ-001\",\n        \"dimension:functional\",\n        \"dimension:permissions\",\n        \"decision:A5-DEC-001\",\n        \"decision:A5-DEC-003\"\n      ],\n      \"reason\": \"El frente comprende el alcance funcional de la comunicación del ahorro a los clientes del piloto y la identificación de los permisos aplicables. La entrada no acredita capacidad funcional exacta, segmentos, canales, autorizaciones ni condiciones de acceso. A5-DEC-001 y A5-DEC-003 permanecen pendientes. La obligación de considerar este frente no constituye aprobación de sus requisitos.\"\n    },\n    {\n      \"front_id\": \"A7-FRONT-002\",\n      \"scope_ids\": [\n        \"A6-REQ-002\",\n        \"A6-REQ-004\",\n        \"dimension:data\"\n      ],\n      \"obligation_mode\": \"REQUIRED\",\n      \"closure\": \"BLOCKED\",\n      \"blockers\": [\n        \"A5-DEC-002\",\n        \"A5-DEC-004\"\n      ],\n      \"evidence_refs\": [\n        \"A6-REQ-002\",\n        \"A6-REQ-004\",\n        \"dimension:data\",\n        \"decision:A5-DEC-002\",\n        \"decision:A5-DEC-004\",\n        \"gap:SAVINGS_SEMANTICS_UNRESOLVED\",\n        \"gap:INSTALLMENT_DISTINCTION_UNRESOLVED\"\n      ],\n      \"reason\": \"El frente agrupa la definición del ahorro, su base de comparación y la distinción funcional respecto del monto de la cuota. No existen definiciones económicas autorizadas ni evidencia suficiente de sus relaciones. No se determinan importes ni reglas de cálculo. Ambas decisiones permanecen pendientes y los requisitos son provisionales.\"\n    },\n    {\n      \"front_id\": \"A7-FRONT-003\",\n      \"scope_ids\": [\n        \"A6-REQ-003\",\n        \"dimension:state\"\n      ],\n      \"obligation_mode\": \"REQUIRED\",\n      \"closure\": \"BLOCKED\",\n      \"blockers\": [\n        \"A5-DEC-003\"\n      ],\n      \"evidence_refs\": [\n        \"A6-REQ-003\",\n        \"dimension:state\",\n        \"decision:A5-DEC-003\",\n        \"gap:OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\"\n      ],\n      \"reason\": \"El frente comprende las condiciones y el momento en que la información del ahorro debe estar disponible antes de aceptar una oferta. No se han acreditado los estados de la oferta, sus transiciones ni las condiciones aplicables. No se inventan estados o comportamientos. A5-DEC-003 sigue pendiente.\"\n    },\n    {\n      \"front_id\": \"A7-FRONT-004\",\n      \"scope_ids\": [\n        \"dimension:errors\",\n        \"dimension:side_effects\"\n      ],\n      \"obligation_mode\": \"REQUIRED\",\n      \"closure\": \"BLOCKED\",\n      \"blockers\": [\n        \"A5-DEC-002\",\n        \"A5-DEC-003\",\n        \"A5-DEC-004\"\n      ],\n      \"evidence_refs\": [\n        \"dimension:errors\",\n        \"dimension:side_effects\",\n        \"decision:A5-DEC-002\",\n        \"decision:A5-DEC-003\",\n        \"decision:A5-DEC-004\"\n      ],\n      \"reason\": \"El frente agrupa los comportamientos ante información económica no disponible, indeterminada o incompatible con las condiciones de la oferta, así como los posibles efectos colaterales asociados. La entrada no proporciona reglas autorizadas para estas dimensiones. No puede afirmarse su existencia, inexistencia o comportamiento concreto. Permanece bloqueado por las decisiones materiales relacionadas.\"\n    },\n    {\n      \"front_id\": \"A7-FRONT-005\",\n      \"scope_ids\": [\n        \"A6-REQ-005\"\n      ],\n      \"obligation_mode\": \"REQUIRED\",\n      \"closure\": \"BLOCKED\",\n      \"blockers\": [\n        \"A5-DEC-004\",\n        \"A5-DEC-005\"\n      ],\n      \"evidence_refs\": [\n        \"A6-REQ-005\",\n        \"decision:A5-DEC-004\",\n        \"decision:A5-DEC-005\",\n        \"gap:ACCEPTANCE_EVIDENCE_MISSING\"\n      ],\n      \"reason\": \"El frente comprende los criterios necesarios para evaluar si los clientes comprenden el ahorro y lo distinguen de la cuota durante el piloto. No se suministran criterios de aceptación autorizados ni evidencia de comprensión verificable. No se inventan métricas, umbrales o resultados. Las decisiones A5-DEC-004 y A5-DEC-005 permanecen pendientes.\"\n    }\n  ],\n  \"evidence_refs\": [\n    \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\",\n    \"supabase://public.lf_eventos/20843\",\n    \"gap:TARGET_AUTHORITY_NOT_SUPPLIED\",\n    \"gap:SAVINGS_SEMANTICS_UNRESOLVED\",\n    \"gap:OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n    \"gap:INSTALLMENT_DISTINCTION_UNRESOLVED\",\n    \"gap:ACCEPTANCE_EVIDENCE_MISSING\",\n    \"A6-REQ-001\",\n    \"A6-REQ-002\",\n    \"A6-REQ-003\",\n    \"A6-REQ-004\",\n    \"A6-REQ-005\",\n    \"dimension:functional\",\n    \"dimension:data\",\n    \"dimension:permissions\",\n    \"dimension:state\",\n    \"dimension:errors\",\n    \"dimension:side_effects\",\n    \"decision:A5-DEC-001\",\n    \"decision:A5-DEC-002\",\n    \"decision:A5-DEC-003\",\n    \"decision:A5-DEC-004\",\n    \"decision:A5-DEC-005\"\n  ],\n  \"fronts_statement\": \"Se identificaron cinco frentes materiales que cubren los cinco requisitos y las seis dimensiones de A6, sin dejar elementos sin vincular. Los frentes comprenden alcance funcional y permisos, información económica, condiciones de la oferta, errores y efectos colaterales, y criterios de comprensión. Todos tienen obligation_mode REQUIRED porque deben considerarse en el análisis, pero ninguno constituye un requisito funcional aprobado. Los cinco permanecen BLOCKED por decisiones A5 pendientes y ausencia de autoridad positiva, evidencia de vigencia y definición suficiente del comportamiento. No se asigna REUSE_AS_IS ni NOT_APPLICABLE porque esas clasificaciones exigirían evidencia positiva que la entrada no proporciona. La cobertura de elementos identificados no demuestra que se hayan descubierto todos los posibles frentes reales del sistema ni que exista autorización para implementar. No se seleccionaron soluciones técnicas ni se resolvieron decisiones del propietario.\"\n}"},{"item_id":"ITEM_B","text":"{\n  \"schema_version\": \"A7_FRONTS_OUTPUT_V1\",\n  \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n  \"material_fronts\": [\n    {\n      \"front_id\": \"A7-FRONT-001\",\n      \"scope_ids\": [\n        \"A6-REQ-001\",\n        \"dimension:functional\",\n        \"dimension:permissions\"\n      ],\n      \"obligation_mode\": \"REQUIRED\",\n      \"closure\": \"BLOCKED\",\n      \"blockers\": [\n        \"A5-DEC-001\",\n        \"A5-DEC-003\"\n      ],\n      \"evidence_refs\": [\n        \"A6-REQ-001\",\n        \"dimension:functional\",\n        \"dimension:permissions\",\n        \"decision:A5-DEC-001\",\n        \"decision:A5-DEC-003\"\n      ],\n      \"reason\": \"El frente comprende el alcance funcional de la comunicación del ahorro a los clientes del piloto y la identificación de los permisos aplicables. La entrada no acredita capacidad funcional exacta, segmentos, canales, autorizaciones ni condiciones de acceso. A5-DEC-001 y A5-DEC-003 permanecen pendientes. La obligación de considerar este frente no constituye aprobación de sus requisitos.\"\n    },\n    {\n      \"front_id\": \"A7-FRONT-002\",\n      \"scope_ids\": [\n        \"A6-REQ-002\",\n        \"A6-REQ-004\",\n        \"dimension:data\"\n      ],\n      \"obligation_mode\": \"REQUIRED\",\n      \"closure\": \"BLOCKED\",\n      \"blockers\": [\n        \"A5-DEC-002\",\n        \"A5-DEC-099\"\n      ],\n      \"evidence_refs\": [\n        \"A6-REQ-002\",\n        \"A6-REQ-004\",\n        \"dimension:data\",\n        \"decision:A5-DEC-002\",\n        \"decision:A5-DEC-004\",\n        \"gap:SAVINGS_SEMANTICS_UNRESOLVED\",\n        \"gap:INSTALLMENT_DISTINCTION_UNRESOLVED\"\n      ],\n      \"reason\": \"El frente agrupa la definición del ahorro, su base de comparación y la distinción funcional respecto del monto de la cuota. No existen definiciones económicas autorizadas ni evidencia suficiente de sus relaciones. No se determinan importes ni reglas de cálculo. Ambas decisiones permanecen pendientes y los requisitos son provisionales.\"\n    },\n    {\n      \"front_id\": \"A7-FRONT-003\",\n      \"scope_ids\": [\n        \"A6-REQ-003\",\n        \"dimension:state\"\n      ],\n      \"obligation_mode\": \"NOT_APPLICABLE\",\n      \"closure\": \"CLOSED\",\n      \"blockers\": [],\n      \"evidence_refs\": [\n        \"A6-REQ-003\",\n        \"dimension:state\",\n        \"decision:A5-DEC-003\",\n        \"gap:OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\"\n      ],\n      \"reason\": \"El frente comprende las condiciones y el momento en que la información del ahorro debe estar disponible antes de aceptar una oferta. No se han acreditado los estados de la oferta, sus transiciones ni las condiciones aplicables. No se inventan estados o comportamientos. A5-DEC-003 sigue pendiente.\"\n    },\n    {\n      \"front_id\": \"A7-FRONT-004\",\n      \"scope_ids\": [\n        \"dimension:errors\",\n        \"dimension:side_effects\"\n      ],\n      \"obligation_mode\": \"REQUIRED\",\n      \"closure\": \"BLOCKED\",\n      \"blockers\": [\n        \"A5-DEC-002\",\n        \"A5-DEC-003\",\n        \"A5-DEC-004\"\n      ],\n      \"evidence_refs\": [\n        \"dimension:errors\",\n        \"dimension:side_effects\",\n        \"decision:A5-DEC-002\",\n        \"decision:A5-DEC-003\",\n        \"decision:A5-DEC-004\"\n      ],\n      \"reason\": \"El frente agrupa los comportamientos ante información económica no disponible, indeterminada o incompatible con las condiciones de la oferta, así como los posibles efectos colaterales asociados. La entrada no proporciona reglas autorizadas para estas dimensiones. No puede afirmarse su existencia, inexistencia o comportamiento concreto. Permanece bloqueado por las decisiones materiales relacionadas.\"\n    },\n    {\n      \"front_id\": \"A7-FRONT-005\",\n      \"scope_ids\": [\n        \"A6-REQ-005\"\n      ],\n      \"obligation_mode\": \"REQUIRED\",\n      \"closure\": \"BLOCKED\",\n      \"blockers\": [\n        \"A5-DEC-004\",\n        \"A5-DEC-005\"\n      ],\n      \"evidence_refs\": [\n        \"A6-REQ-005\",\n        \"decision:A5-DEC-004\",\n        \"decision:A5-DEC-005\",\n        \"gap:ACCEPTANCE_EVIDENCE_MISSING\"\n      ],\n      \"reason\": \"El frente comprende los criterios necesarios para evaluar si los clientes comprenden el ahorro y lo distinguen de la cuota durante el piloto. No se suministran criterios de aceptación autorizados ni evidencia de comprensión verificable. No se inventan métricas, umbrales o resultados. Las decisiones A5-DEC-004 y A5-DEC-005 permanecen pendientes.\"\n    }\n  ],\n  \"evidence_refs\": [\n    \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\",\n    \"supabase://public.lf_eventos/20843\",\n    \"gap:TARGET_AUTHORITY_NOT_SUPPLIED\",\n    \"gap:SAVINGS_SEMANTICS_UNRESOLVED\",\n    \"gap:OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n    \"gap:INSTALLMENT_DISTINCTION_UNRESOLVED\",\n    \"gap:ACCEPTANCE_EVIDENCE_MISSING\",\n    \"A6-REQ-001\",\n    \"A6-REQ-002\",\n    \"A6-REQ-003\",\n    \"A6-REQ-004\",\n    \"A6-REQ-005\",\n    \"dimension:functional\",\n    \"dimension:data\",\n    \"dimension:permissions\",\n    \"dimension:state\",\n    \"dimension:errors\",\n    \"dimension:side_effects\",\n    \"decision:A5-DEC-001\",\n    \"decision:A5-DEC-002\",\n    \"decision:A5-DEC-003\",\n    \"decision:A5-DEC-004\",\n    \"decision:A5-DEC-005\"\n  ],\n  \"fronts_statement\": \"Se identificaron cinco frentes materiales que cubren los cinco requisitos y las seis dimensiones de A6, sin dejar elementos sin vincular. Los frentes comprenden alcance funcional y permisos, información económica, condiciones de la oferta, errores y efectos colaterales, y criterios de comprensión. Todos tienen obligation_mode REQUIRED porque deben considerarse en el análisis, pero ninguno constituye un requisito funcional aprobado. Los cinco permanecen BLOCKED por decisiones A5 pendientes y ausencia de autoridad positiva, evidencia de vigencia y definición suficiente del comportamiento. No se asigna REUSE_AS_IS ni NOT_APPLICABLE porque esas clasificaciones exigirían evidencia positiva que la entrada no proporciona. La cobertura de elementos identificados no demuestra que se hayan descubierto todos los posibles frentes reales del sistema ni que exista autorización para implementar. No se seleccionaron soluciones técnicas ni se resolvieron decisiones del propietario.\"\n}"}],"limits":{"independent_review":false,"provider_attested":false,"real_execution_receipt":false},"packet_sha256":"e8fa9887a169c46ee7e375c7b5c5b234cda3ce0ec05fc6d8e50aa5a6c21fdae9","prompt_for_gpt":"Eres un revisor independiente. No produjiste ninguno de los ítems de abajo y no conoces quién los produjo. Evalúa cada ítem POR SEPARADO contra cada chequeo, usando solo la solicitud literal y el texto del ítem.\n\nCRITERIO: Juez comprueba cobertura, evidencias de NA/REUSE y frentes BLOCKED\n\nCHEQUEOS (evalúa cada uno, PASS o FAIL):\n- COVERAGE_COMPLETE: Cada requirement_id y cada 'dimension:<nombre>' de la entrada queda vinculado a al menos un frente; no se inventan frentes que la entrada no sustente.\n- NO_NA_REUSE_WITHOUT_EVIDENCE: No hay frentes NOT_APPLICABLE ni REUSE_AS_IS: la entrada no trae autoridad positiva ni evidencia de vigencia que los respalde.\n- BLOCKED_FRONTS_VALID: Todo frente está BLOCKED y sus blockers son decision_id que existen en la entrada; las referencias son válidas y no se propone solución técnica.\n\nREGLAS DE LA ETAPA (con las que se produjo el ítem; úsalas solo para juzgar, no para producir nada):\nAgrupa en frentes materiales todo lo que la entrada obliga a considerar, sin inventar frentes que la entrada no sustente. Cada requisito (requirement_id) y cada dimensión (como 'dimension:<nombre>') de la entrada debe quedar vinculado a al menos un frente. La entrada no trae autoridad positiva ni evidencia de vigencia: por eso NO_APPLICABLE y REUSE_AS_IS están prohibidos, y todo frente queda BLOCKED con bloqueadores que sean decision_id de la entrada. No propongas soluciones técnicas. Referencias válidas: las evidence_refs de la entrada, los requirement_id, 'dimension:<nombre>' y 'decision:<decision_id>'. Devuelve SOLO un objeto JSON, sin texto adicional, con exactamente estas claves: schema_version, request_ref, material_fronts, evidence_refs, fronts_statement. schema_version='A7_FRONTS_OUTPUT_V1'. request_ref='REQ-LF-A1Q-C2-PILOT-0001'. material_fronts: lista de {front_id (único), scope_ids (lista no vacía de requirement_id o 'dimension:<nombre>' de la entrada), obligation_mode (REQUIRED|REUSE_AS_IS|NOT_APPLICABLE), closure (CLOSED|BLOCKED), blockers (lista de decision_id de la entrada), evidence_refs (lista no vacía de referencias válidas), reason (texto)}; al menos 3 frentes. evidence_refs: lista no vacía de referencias válidas. fronts_statement: texto que explica qué frentes quedan bloqueados y por qué.\n\nSOLICITUD LITERAL (entrada):\n{\n  \"a6_stage_output\": {\n    \"dimensions\": {\n      \"data\": {\n        \"blocked_by\": [\n          \"A5-DEC-002\",\n          \"A5-DEC-004\"\n        ],\n        \"note\": \"Se identifican como conceptos materiales el ahorro y el monto de la cuota. No están autorizadas sus definiciones, valores, bases de comparación ni relaciones. No se presuponen importes ni reglas de cálculo.\",\n        \"status\": \"PROVISIONAL_PENDING_DECISION\"\n      },\n      \"errors\": {\n        \"blocked_by\": [\n          \"A5-DEC-002\",\n          \"A5-DEC-003\"\n        ],\n        \"note\": \"No se suministran comportamientos autorizados frente a información de ahorro no disponible, indeterminada o incompatible con las condiciones de la oferta. No se establecen resultados de error sin evidencia.\",\n        \"status\": \"BLOCKED_UNDETERMINED\"\n      },\n      \"functional\": {\n        \"blocked_by\": [\n          \"A5-DEC-001\",\n          \"A5-DEC-002\",\n          \"A5-DEC-003\",\n          \"A5-DEC-004\"\n        ],\n        \"note\": \"Se identifican las obligaciones funcionales de comunicar el ahorro antes de aceptar una oferta y distinguirlo de la cuota. Su alcance, significado y condiciones permanecen pendientes de decisión.\",\n        \"status\": \"PROVISIONAL_PENDING_DECISION\"\n      },\n      \"permissions\": {\n        \"blocked_by\": [\n          \"A5-DEC-001\"\n        ],\n        \"note\": \"La entrada no proporciona evidencia de permisos, roles autorizados ni reglas de acceso. No se establecen permisos por inferencia.\",\n        \"status\": \"BLOCKED_UNDETERMINED\"\n      },\n      \"side_effects\": {\n        \"blocked_by\": [\n          \"A5-DEC-003\",\n          \"A5-DEC-004\"\n        ],\n        \"note\": \"No se conocen efectos colaterales autorizados asociados a comunicar el ahorro, distinguir cuotas o aceptar ofertas. No se afirma que existan ni que estén ausentes.\",\n        \"status\": \"BLOCKED_UNDETERMINED\"\n      },\n      \"state\": {\n        \"blocked_by\": [\n          \"A5-DEC-003\"\n        ],\n        \"note\": \"No existe evidencia suficiente sobre los estados de la oferta, sus transiciones o las condiciones que habilitan comunicar el ahorro. No se inventan estados.\",\n        \"status\": \"BLOCKED_UNDETERMINED\"\n      }\n    },\n    \"evidence_refs\": [\n      \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\",\n      \"supabase://public.lf_eventos/20843\",\n      \"gap:TARGET_AUTHORITY_NOT_SUPPLIED\",\n      \"gap:SAVINGS_SEMANTICS_UNRESOLVED\",\n      \"gap:OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n      \"gap:INSTALLMENT_DISTINCTION_UNRESOLVED\",\n      \"gap:ACCEPTANCE_EVIDENCE_MISSING\",\n      \"decision:A5-DEC-001\",\n      \"decision:A5-DEC-002\",\n      \"decision:A5-DEC-003\",\n      \"decision:A5-DEC-004\",\n      \"decision:A5-DEC-005\"\n    ],\n    \"no_unlicensed_how\": true,\n    \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n    \"requirements\": [\n      {\n        \"depends_on_decisions\": [\n          \"A5-DEC-001\",\n          \"A5-DEC-003\"\n        ],\n        \"requirement_id\": \"A6-REQ-001\",\n        \"source_ref\": \"decision:A5-DEC-001\",\n        \"statement\": \"Los clientes comprendidos en el alcance autorizado del piloto deberán poder conocer el ahorro asociado a la negociación de su deuda antes de aceptar una oferta, conforme a las condiciones funcionales que se determinen.\",\n        \"status\": \"PROVISIONAL_PENDING_DECISION\",\n        \"type\": \"FUNCTIONAL\"\n      },\n      {\n        \"depends_on_decisions\": [\n          \"A5-DEC-002\"\n        ],\n        \"requirement_id\": \"A6-REQ-002\",\n        \"source_ref\": \"decision:A5-DEC-002\",\n        \"statement\": \"La información del ahorro deberá corresponder a una definición y una base de comparación autorizadas, todavía pendientes de determinar.\",\n        \"status\": \"PROVISIONAL_PENDING_DECISION\",\n        \"type\": \"DATA\"\n      },\n      {\n        \"depends_on_decisions\": [\n          \"A5-DEC-003\"\n        ],\n        \"requirement_id\": \"A6-REQ-003\",\n        \"source_ref\": \"decision:A5-DEC-003\",\n        \"statement\": \"La disponibilidad de la información del ahorro deberá respetar el momento y las condiciones autorizadas de la oferta antes de su aceptación.\",\n        \"status\": \"PROVISIONAL_PENDING_DECISION\",\n        \"type\": \"FUNCTIONAL\"\n      },\n      {\n        \"depends_on_decisions\": [\n          \"A5-DEC-002\",\n          \"A5-DEC-004\"\n        ],\n        \"requirement_id\": \"A6-REQ-004\",\n        \"source_ref\": \"decision:A5-DEC-004\",\n        \"statement\": \"La información comunicada al cliente deberá permitir distinguir el ahorro de la negociación del monto de la cuota, conforme a las definiciones funcionales que resulten autorizadas.\",\n        \"status\": \"PROVISIONAL_PENDING_DECISION\",\n        \"type\": \"FUNCTIONAL\"\n      },\n      {\n        \"depends_on_decisions\": [\n          \"A5-DEC-004\",\n          \"A5-DEC-005\"\n        ],\n        \"requirement_id\": \"A6-REQ-005\",\n        \"source_ref\": \"decision:A5-DEC-005\",\n        \"statement\": \"La claridad de la información sobre ahorro y cuota deberá poder evaluarse mediante criterios de comprensión y aceptación previamente autorizados para el piloto.\",\n        \"status\": \"PROVISIONAL_PENDING_DECISION\",\n        \"type\": \"NON_FUNCTIONAL\"\n      }\n    ],\n    \"requirements_statement\": \"Se formularon cinco requisitos provisionales, de naturaleza funcional, de datos y no funcional, vinculados a las cinco decisiones pendientes de A5. Ninguno constituye una obligación aprobada ni una autorización de implementación. Las dimensiones funcional y de datos contienen únicamente necesidades condicionadas. Permisos, estados, errores y efectos colaterales permanecen BLOCKED_UNDETERMINED por falta de evidencia. También están pendientes la verificación de autoridad vigente, la identificación de la implementación existente y la línea base AS-IS. El resultado expresa exclusivamente QUÉ se necesita definir y cumplir, sin seleccionar tecnología, diseño, estructuras internas, reglas económicas no autorizadas ni decisiones de producto.\",\n    \"schema_version\": \"A6_REQUIREMENTS_OUTPUT_V1\"\n  }\n}\n\n<<<ITEM_A>>>\n{\n  \"schema_version\": \"A7_FRONTS_OUTPUT_V1\",\n  \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n  \"material_fronts\": [\n    {\n      \"front_id\": \"A7-FRONT-001\",\n      \"scope_ids\": [\n        \"A6-REQ-001\",\n        \"dimension:functional\",\n        \"dimension:permissions\"\n      ],\n      \"obligation_mode\": \"REQUIRED\",\n      \"closure\": \"BLOCKED\",\n      \"blockers\": [\n        \"A5-DEC-001\",\n        \"A5-DEC-003\"\n      ],\n      \"evidence_refs\": [\n        \"A6-REQ-001\",\n        \"dimension:functional\",\n        \"dimension:permissions\",\n        \"decision:A5-DEC-001\",\n        \"decision:A5-DEC-003\"\n      ],\n      \"reason\": \"El frente comprende el alcance funcional de la comunicación del ahorro a los clientes del piloto y la identificación de los permisos aplicables. La entrada no acredita capacidad funcional exacta, segmentos, canales, autorizaciones ni condiciones de acceso. A5-DEC-001 y A5-DEC-003 permanecen pendientes. La obligación de considerar este frente no constituye aprobación de sus requisitos.\"\n    },\n    {\n      \"front_id\": \"A7-FRONT-002\",\n      \"scope_ids\": [\n        \"A6-REQ-002\",\n        \"A6-REQ-004\",\n        \"dimension:data\"\n      ],\n      \"obligation_mode\": \"REQUIRED\",\n      \"closure\": \"BLOCKED\",\n      \"blockers\": [\n        \"A5-DEC-002\",\n        \"A5-DEC-004\"\n      ],\n      \"evidence_refs\": [\n        \"A6-REQ-002\",\n        \"A6-REQ-004\",\n        \"dimension:data\",\n        \"decision:A5-DEC-002\",\n        \"decision:A5-DEC-004\",\n        \"gap:SAVINGS_SEMANTICS_UNRESOLVED\",\n        \"gap:INSTALLMENT_DISTINCTION_UNRESOLVED\"\n      ],\n      \"reason\": \"El frente agrupa la definición del ahorro, su base de comparación y la distinción funcional respecto del monto de la cuota. No existen definiciones económicas autorizadas ni evidencia suficiente de sus relaciones. No se determinan importes ni reglas de cálculo. Ambas decisiones permanecen pendientes y los requisitos son provisionales.\"\n    },\n    {\n      \"front_id\": \"A7-FRONT-003\",\n      \"scope_ids\": [\n        \"A6-REQ-003\",\n        \"dimension:state\"\n      ],\n      \"obligation_mode\": \"REQUIRED\",\n      \"closure\": \"BLOCKED\",\n      \"blockers\": [\n        \"A5-DEC-003\"\n      ],\n      \"evidence_refs\": [\n        \"A6-REQ-003\",\n        \"dimension:state\",\n        \"decision:A5-DEC-003\",\n        \"gap:OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\"\n      ],\n      \"reason\": \"El frente comprende las condiciones y el momento en que la información del ahorro debe estar disponible antes de aceptar una oferta. No se han acreditado los estados de la oferta, sus transiciones ni las condiciones aplicables. No se inventan estados o comportamientos. A5-DEC-003 sigue pendiente.\"\n    },\n    {\n      \"front_id\": \"A7-FRONT-004\",\n      \"scope_ids\": [\n        \"dimension:errors\",\n        \"dimension:side_effects\"\n      ],\n      \"obligation_mode\": \"REQUIRED\",\n      \"closure\": \"BLOCKED\",\n      \"blockers\": [\n        \"A5-DEC-002\",\n        \"A5-DEC-003\",\n        \"A5-DEC-004\"\n      ],\n      \"evidence_refs\": [\n        \"dimension:errors\",\n        \"dimension:side_effects\",\n        \"decision:A5-DEC-002\",\n        \"decision:A5-DEC-003\",\n        \"decision:A5-DEC-004\"\n      ],\n      \"reason\": \"El frente agrupa los comportamientos ante información económica no disponible, indeterminada o incompatible con las condiciones de la oferta, así como los posibles efectos colaterales asociados. La entrada no proporciona reglas autorizadas para estas dimensiones. No puede afirmarse su existencia, inexistencia o comportamiento concreto. Permanece bloqueado por las decisiones materiales relacionadas.\"\n    },\n    {\n      \"front_id\": \"A7-FRONT-005\",\n      \"scope_ids\": [\n        \"A6-REQ-005\"\n      ],\n      \"obligation_mode\": \"REQUIRED\",\n      \"closure\": \"BLOCKED\",\n      \"blockers\": [\n        \"A5-DEC-004\",\n        \"A5-DEC-005\"\n      ],\n      \"evidence_refs\": [\n        \"A6-REQ-005\",\n        \"decision:A5-DEC-004\",\n        \"decision:A5-DEC-005\",\n        \"gap:ACCEPTANCE_EVIDENCE_MISSING\"\n      ],\n      \"reason\": \"El frente comprende los criterios necesarios para evaluar si los clientes comprenden el ahorro y lo distinguen de la cuota durante el piloto. No se suministran criterios de aceptación autorizados ni evidencia de comprensión verificable. No se inventan métricas, umbrales o resultados. Las decisiones A5-DEC-004 y A5-DEC-005 permanecen pendientes.\"\n    }\n  ],\n  \"evidence_refs\": [\n    \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\",\n    \"supabase://public.lf_eventos/20843\",\n    \"gap:TARGET_AUTHORITY_NOT_SUPPLIED\",\n    \"gap:SAVINGS_SEMANTICS_UNRESOLVED\",\n    \"gap:OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n    \"gap:INSTALLMENT_DISTINCTION_UNRESOLVED\",\n    \"gap:ACCEPTANCE_EVIDENCE_MISSING\",\n    \"A6-REQ-001\",\n    \"A6-REQ-002\",\n    \"A6-REQ-003\",\n    \"A6-REQ-004\",\n    \"A6-REQ-005\",\n    \"dimension:functional\",\n    \"dimension:data\",\n    \"dimension:permissions\",\n    \"dimension:state\",\n    \"dimension:errors\",\n    \"dimension:side_effects\",\n    \"decision:A5-DEC-001\",\n    \"decision:A5-DEC-002\",\n    \"decision:A5-DEC-003\",\n    \"decision:A5-DEC-004\",\n    \"decision:A5-DEC-005\"\n  ],\n  \"fronts_statement\": \"Se identificaron cinco frentes materiales que cubren los cinco requisitos y las seis dimensiones de A6, sin dejar elementos sin vincular. Los frentes comprenden alcance funcional y permisos, información económica, condiciones de la oferta, errores y efectos colaterales, y criterios de comprensión. Todos tienen obligation_mode REQUIRED porque deben considerarse en el análisis, pero ninguno constituye un requisito funcional aprobado. Los cinco permanecen BLOCKED por decisiones A5 pendientes y ausencia de autoridad positiva, evidencia de vigencia y definición suficiente del comportamiento. No se asigna REUSE_AS_IS ni NOT_APPLICABLE porque esas clasificaciones exigirían evidencia positiva que la entrada no proporciona. La cobertura de elementos identificados no demuestra que se hayan descubierto todos los posibles frentes reales del sistema ni que exista autorización para implementar. No se seleccionaron soluciones técnicas ni se resolvieron decisiones del propietario.\"\n}\n<<<FIN ITEM_A>>>\n\n<<<ITEM_B>>>\n{\n  \"schema_version\": \"A7_FRONTS_OUTPUT_V1\",\n  \"request_ref\": \"REQ-LF-A1Q-C2-PILOT-0001\",\n  \"material_fronts\": [\n    {\n      \"front_id\": \"A7-FRONT-001\",\n      \"scope_ids\": [\n        \"A6-REQ-001\",\n        \"dimension:functional\",\n        \"dimension:permissions\"\n      ],\n      \"obligation_mode\": \"REQUIRED\",\n      \"closure\": \"BLOCKED\",\n      \"blockers\": [\n        \"A5-DEC-001\",\n        \"A5-DEC-003\"\n      ],\n      \"evidence_refs\": [\n        \"A6-REQ-001\",\n        \"dimension:functional\",\n        \"dimension:permissions\",\n        \"decision:A5-DEC-001\",\n        \"decision:A5-DEC-003\"\n      ],\n      \"reason\": \"El frente comprende el alcance funcional de la comunicación del ahorro a los clientes del piloto y la identificación de los permisos aplicables. La entrada no acredita capacidad funcional exacta, segmentos, canales, autorizaciones ni condiciones de acceso. A5-DEC-001 y A5-DEC-003 permanecen pendientes. La obligación de considerar este frente no constituye aprobación de sus requisitos.\"\n    },\n    {\n      \"front_id\": \"A7-FRONT-002\",\n      \"scope_ids\": [\n        \"A6-REQ-002\",\n        \"A6-REQ-004\",\n        \"dimension:data\"\n      ],\n      \"obligation_mode\": \"REQUIRED\",\n      \"closure\": \"BLOCKED\",\n      \"blockers\": [\n        \"A5-DEC-002\",\n        \"A5-DEC-099\"\n      ],\n      \"evidence_refs\": [\n        \"A6-REQ-002\",\n        \"A6-REQ-004\",\n        \"dimension:data\",\n        \"decision:A5-DEC-002\",\n        \"decision:A5-DEC-004\",\n        \"gap:SAVINGS_SEMANTICS_UNRESOLVED\",\n        \"gap:INSTALLMENT_DISTINCTION_UNRESOLVED\"\n      ],\n      \"reason\": \"El frente agrupa la definición del ahorro, su base de comparación y la distinción funcional respecto del monto de la cuota. No existen definiciones económicas autorizadas ni evidencia suficiente de sus relaciones. No se determinan importes ni reglas de cálculo. Ambas decisiones permanecen pendientes y los requisitos son provisionales.\"\n    },\n    {\n      \"front_id\": \"A7-FRONT-003\",\n      \"scope_ids\": [\n        \"A6-REQ-003\",\n        \"dimension:state\"\n      ],\n      \"obligation_mode\": \"NOT_APPLICABLE\",\n      \"closure\": \"CLOSED\",\n      \"blockers\": [],\n      \"evidence_refs\": [\n        \"A6-REQ-003\",\n        \"dimension:state\",\n        \"decision:A5-DEC-003\",\n        \"gap:OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\"\n      ],\n      \"reason\": \"El frente comprende las condiciones y el momento en que la información del ahorro debe estar disponible antes de aceptar una oferta. No se han acreditado los estados de la oferta, sus transiciones ni las condiciones aplicables. No se inventan estados o comportamientos. A5-DEC-003 sigue pendiente.\"\n    },\n    {\n      \"front_id\": \"A7-FRONT-004\",\n      \"scope_ids\": [\n        \"dimension:errors\",\n        \"dimension:side_effects\"\n      ],\n      \"obligation_mode\": \"REQUIRED\",\n      \"closure\": \"BLOCKED\",\n      \"blockers\": [\n        \"A5-DEC-002\",\n        \"A5-DEC-003\",\n        \"A5-DEC-004\"\n      ],\n      \"evidence_refs\": [\n        \"dimension:errors\",\n        \"dimension:side_effects\",\n        \"decision:A5-DEC-002\",\n        \"decision:A5-DEC-003\",\n        \"decision:A5-DEC-004\"\n      ],\n      \"reason\": \"El frente agrupa los comportamientos ante información económica no disponible, indeterminada o incompatible con las condiciones de la oferta, así como los posibles efectos colaterales asociados. La entrada no proporciona reglas autorizadas para estas dimensiones. No puede afirmarse su existencia, inexistencia o comportamiento concreto. Permanece bloqueado por las decisiones materiales relacionadas.\"\n    },\n    {\n      \"front_id\": \"A7-FRONT-005\",\n      \"scope_ids\": [\n        \"A6-REQ-005\"\n      ],\n      \"obligation_mode\": \"REQUIRED\",\n      \"closure\": \"BLOCKED\",\n      \"blockers\": [\n        \"A5-DEC-004\",\n        \"A5-DEC-005\"\n      ],\n      \"evidence_refs\": [\n        \"A6-REQ-005\",\n        \"decision:A5-DEC-004\",\n        \"decision:A5-DEC-005\",\n        \"gap:ACCEPTANCE_EVIDENCE_MISSING\"\n      ],\n      \"reason\": \"El frente comprende los criterios necesarios para evaluar si los clientes comprenden el ahorro y lo distinguen de la cuota durante el piloto. No se suministran criterios de aceptación autorizados ni evidencia de comprensión verificable. No se inventan métricas, umbrales o resultados. Las decisiones A5-DEC-004 y A5-DEC-005 permanecen pendientes.\"\n    }\n  ],\n  \"evidence_refs\": [\n    \"supabase://programacion.engineering_plan_units/A1Q#unit_metadata.gpt_native_packets_v1.A1Q_C2\",\n    \"supabase://public.lf_eventos/20843\",\n    \"gap:TARGET_AUTHORITY_NOT_SUPPLIED\",\n    \"gap:SAVINGS_SEMANTICS_UNRESOLVED\",\n    \"gap:OFFER_ACCEPTANCE_BOUNDARY_UNRESOLVED\",\n    \"gap:INSTALLMENT_DISTINCTION_UNRESOLVED\",\n    \"gap:ACCEPTANCE_EVIDENCE_MISSING\",\n    \"A6-REQ-001\",\n    \"A6-REQ-002\",\n    \"A6-REQ-003\",\n    \"A6-REQ-004\",\n    \"A6-REQ-005\",\n    \"dimension:functional\",\n    \"dimension:data\",\n    \"dimension:permissions\",\n    \"dimension:state\",\n    \"dimension:errors\",\n    \"dimension:side_effects\",\n    \"decision:A5-DEC-001\",\n    \"decision:A5-DEC-002\",\n    \"decision:A5-DEC-003\",\n    \"decision:A5-DEC-004\",\n    \"decision:A5-DEC-005\"\n  ],\n  \"fronts_statement\": \"Se identificaron cinco frentes materiales que cubren los cinco requisitos y las seis dimensiones de A6, sin dejar elementos sin vincular. Los frentes comprenden alcance funcional y permisos, información económica, condiciones de la oferta, errores y efectos colaterales, y criterios de comprensión. Todos tienen obligation_mode REQUIRED porque deben considerarse en el análisis, pero ninguno constituye un requisito funcional aprobado. Los cinco permanecen BLOCKED por decisiones A5 pendientes y ausencia de autoridad positiva, evidencia de vigencia y definición suficiente del comportamiento. No se asigna REUSE_AS_IS ni NOT_APPLICABLE porque esas clasificaciones exigirían evidencia positiva que la entrada no proporciona. La cobertura de elementos identificados no demuestra que se hayan descubierto todos los posibles frentes reales del sistema ni que exista autorización para implementar. No se seleccionaron soluciones técnicas ni se resolvieron decisiones del propietario.\"\n}\n<<<FIN ITEM_B>>>\n\nResponde SOLO con un objeto JSON, sin texto adicional, con exactamente estas claves: schema_version ('ANALYSIS_GPT_NATIVE_BLIND_REVIEW_V1'), unit ('A7Q'), items. items es una lista de dos objetos, en el orden ITEM_A, ITEM_B, cada uno con exactamente: item_id, checks, verdict, rationale. checks es una lista con un objeto por chequeo, en el orden dado, con exactamente: code, result (PASS|FAIL), evidence_refs (1 a 3 citas textuales, copiadas LITERALMENTE de la solicitud o del ítem, cada una de al menos 8 caracteres: cita la frase o el fragmento que contiene el dato, no etiquetas sueltas como 'L1'; sin comillas ni saltos de línea), note (una frase). verdict es PASS solo si los tres chequeos son PASS; si no, FAIL. rationale: 1 a 3 frases. No asumas que un ítem es correcto o incorrecto por su posición.","rules_text":"Agrupa en frentes materiales todo lo que la entrada obliga a considerar, sin inventar frentes que la entrada no sustente. Cada requisito (requirement_id) y cada dimensión (como 'dimension:<nombre>') de la entrada debe quedar vinculado a al menos un frente. La entrada no trae autoridad positiva ni evidencia de vigencia: por eso NO_APPLICABLE y REUSE_AS_IS están prohibidos, y todo frente queda BLOCKED con bloqueadores que sean decision_id de la entrada. No propongas soluciones técnicas. Referencias válidas: las evidence_refs de la entrada, los requirement_id, 'dimension:<nombre>' y 'decision:<decision_id>'. Devuelve SOLO un objeto JSON, sin texto adicional, con exactamente estas claves: schema_version, request_ref, material_fronts, evidence_refs, fronts_statement. schema_version='A7_FRONTS_OUTPUT_V1'. request_ref='REQ-LF-A1Q-C2-PILOT-0001'. material_fronts: lista de {front_id (único), scope_ids (lista no vacía de requirement_id o 'dimension:<nombre>' de la entrada), obligation_mode (REQUIRED|REUSE_AS_IS|NOT_APPLICABLE), closure (CLOSED|BLOCKED), blockers (lista de decision_id de la entrada), evidence_refs (lista no vacía de referencias válidas), reason (texto)}; al menos 3 frentes. evidence_refs: lista no vacía de referencias válidas. fronts_statement: texto que explica qué frentes quedan bloqueados y por qué.","schema":"ANALYSIS_GPT_NATIVE_C3_PACKET_V1","subject_ref":"PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1/A7Q/A7Q_C3","unit":"A7"}$pkt$;
 v_key jsonb := $key${"c2_chat_transcript_ref":"https://chatgpt.com/g/g-p-6a6d99aa6330819180764b10e86c9392-agente-de-programacion/c/6acef59c-df30-83e8-accd-609d3b78e0bf","c2_raw_output_sha256":"6bbeadcc8ac1c69d239aec02af75d6a0e153a745c1954703e6c4811c001173fa","decoy_item_id":"ITEM_B","decoy_must_fail_checks":["NO_NA_REUSE_WITHOUT_EVIDENCE","BLOCKED_FRONTS_VALID"],"decoy_sha256":"97645322767a5c4b41d3fafde2a38bff7931b1bd066556cbf3174d6c8a84b993","real_item_id":"ITEM_A","replacements":[["\"obligation_mode\": \"REQUIRED\",\n      \"closure\": \"BLOCKED\",\n      \"blockers\": [\n        \"A5-DEC-003\"\n      ],","\"obligation_mode\": \"NOT_APPLICABLE\",\n      \"closure\": \"CLOSED\",\n      \"blockers\": [],"],["\"blockers\": [\n        \"A5-DEC-002\",\n        \"A5-DEC-004\"\n      ],","\"blockers\": [\n        \"A5-DEC-002\",\n        \"A5-DEC-099\"\n      ],"]]}$key$;
 v_m jsonb; v_cap jsonb; v_raw text; v_decoy text; v_old text; v_new text; v_e jsonb; v_before_specs jsonb; v_before_cps text; v_after_cps text; v_id bigint; v_p jsonb;
BEGIN
 IF v_packet->>'subject_ref' <> v_plan||'/'||v_unit||'/'||v_cp OR v_packet->>'packet_sha256' <> v_packet_sha THEN RAISE EXCEPTION 'A7Q_C3_PACKET_IDENTITY'; END IF;
 IF (v_packet#>>'{limits,provider_attested}')::boolean IS NOT FALSE OR (v_packet#>>'{limits,independent_review}')::boolean IS NOT FALSE
  THEN RAISE EXCEPTION 'A7Q_C3_LIMITS_NOT_FALSE'; END IF;
 IF (SELECT status FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi AND checkpoint_code=v_c2) IS DISTINCT FROM 'DONE'
    OR (SELECT status FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi AND checkpoint_code=v_cp) IS DISTINCT FROM 'PENDING'
  THEN RAISE EXCEPTION 'A7Q_C3_STATE'; END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_before_cps FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi FOR UPDATE;
 IF v_m IS NULL THEN RAISE EXCEPTION 'A7Q_UNIT_NOT_FOUND'; END IF;
 v_cap := v_m#>'{gpt_native_captures_v1,A7Q_C2}';
 IF v_cap IS NULL OR encode(sha256(convert_to(v_cap->>'raw_output_text','UTF8')),'hex') <> v_cap->>'raw_output_sha256'
    OR v_cap->>'raw_output_sha256' <> v_key->>'c2_raw_output_sha256' OR v_cap->>'chat_transcript_ref' <> v_key->>'c2_chat_transcript_ref'
  THEN RAISE EXCEPTION 'A7Q_C3_C2_CAPTURE_BINDING'; END IF;
 IF v_packet->'input' IS DISTINCT FROM (v_m#>'{gpt_native_packets_v1,A7Q_C2,input}') THEN RAISE EXCEPTION 'A7Q_C3_INPUT_NOT_C2_INPUT'; END IF;
 IF v_packet->>'rules_text' IS NOT NULL AND position(v_packet->>'rules_text' in (v_m#>>'{gpt_native_packets_v1,A7Q_C2,prompt_for_gpt}'))=0 THEN RAISE EXCEPTION 'A7Q_C3_RULES_NOT_FROM_C2_PROMPT'; END IF;
 IF v_packet->>'rules_text' IS NOT NULL AND position(v_packet->>'rules_text' in (v_packet->>'prompt_for_gpt'))=0 THEN RAISE EXCEPTION 'A7Q_C3_RULES_NOT_IN_PROMPT'; END IF;
 v_raw := v_cap->>'raw_output_text'; v_decoy := v_raw;
 FOR v_e IN SELECT * FROM jsonb_array_elements(v_key->'replacements') LOOP
  v_old := v_e->>0; v_new := v_e->>1;
  IF (length(v_raw)-length(replace(v_raw,v_old,'')))<>length(v_old) THEN RAISE EXCEPTION 'A7Q_C3_DECOY_REPLACEMENT_NOT_UNIQUE'; END IF;
  v_decoy := replace(v_decoy,v_old,v_new);
 END LOOP;
 IF v_decoy = v_raw OR encode(sha256(convert_to(v_decoy,'UTF8')),'hex') <> v_key->>'decoy_sha256' THEN RAISE EXCEPTION 'A7Q_C3_DECOY_MISMATCH'; END IF;
 PERFORM v_decoy::jsonb;
 IF (SELECT text FROM jsonb_to_recordset(v_packet->'items') AS i(item_id text, text text) WHERE item_id=v_key->>'real_item_id') IS DISTINCT FROM v_raw
    OR (SELECT text FROM jsonb_to_recordset(v_packet->'items') AS i(item_id text, text text) WHERE item_id=v_key->>'decoy_item_id') IS DISTINCT FROM v_decoy
    OR jsonb_array_length(v_packet->'items')<>2 THEN RAISE EXCEPTION 'A7Q_C3_ITEMS_NOT_FROM_C2'; END IF;
 IF position(v_cap->>'chat_transcript_ref' in v_packet->>'prompt_for_gpt')>0 OR position('DECOY' in v_packet::text)>0 OR position('REAL' in v_packet->>'prompt_for_gpt')>0
  THEN RAISE EXCEPTION 'A7Q_C3_PACKET_NOT_BLIND'; END IF;
 IF v_m#>'{gpt_native_packets_v1,A7Q_C3}' IS NOT NULL AND v_m#>>'{gpt_native_packets_v1,A7Q_C3,packet_sha256}' <> v_packet_sha
    AND NOT (v_key->>'supersedes_packet_sha256' IS NOT NULL AND v_m#>>'{gpt_native_packets_v1,A7Q_C3,packet_sha256}' = v_key->>'supersedes_packet_sha256' AND v_m#>'{gpt_native_captures_v1,A7Q_C3}' IS NULL)
  THEN RAISE EXCEPTION 'A7Q_C3_PACKET_DIFFERENT_ALREADY_STORED'; END IF;
 v_before_specs := v_m->'action_specs_v1';
 UPDATE programacion.engineering_plan_units SET unit_metadata = v_m
   || jsonb_build_object('gpt_native_packets_v1', COALESCE(v_m->'gpt_native_packets_v1','{}'::jsonb) || jsonb_build_object('A7Q_C3',v_packet))
   || jsonb_build_object('gpt_native_c3_keys_v1', COALESCE(v_m->'gpt_native_c3_keys_v1','{}'::jsonb) || jsonb_build_object('A7Q_C3',v_key))
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 IF v_m#>'{gpt_native_packets_v1,A7Q_C3}' IS DISTINCT FROM v_packet OR v_m#>'{gpt_native_c3_keys_v1,A7Q_C3}' IS DISTINCT FROM v_key THEN RAISE EXCEPTION 'A7Q_C3_READBACK_MISMATCH'; END IF;
 IF v_m->'action_specs_v1' IS DISTINCT FROM v_before_specs THEN RAISE EXCEPTION 'A7Q_C3_SPECS_CHANGED'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.lf_eventos WHERE evento_tipo='HANDOFF_DEEP_CONTEXT' AND created_by_execution_id=v_exec) THEN
  INSERT INTO public.lf_eventos(evento_tipo,entidad_tipo,entidad_codigo,descripcion,severidad,origen,created_by_execution_id,payload)
  VALUES('HANDOFF_DEEP_CONTEXT','PROGRAM_PLAN',v_plan||'.A7Q_C3.GPT_NATIVE_HANDOFF',
   'Blinded A7Q_C3 review packet handed to a separate GPT Native chat; no acceptance declared.','INFO','DERIVE_FROM_EXECUTION_ID',v_exec,
   jsonb_build_object('evidence_schema_version','operational-event/v2','execution_id',v_exec,'producer','ANALYSIS_QUAL_C3_GPT_HANDOFF_V1',
    'purpose','Hand the blinded A7Q_C3 review packet to GPT Native in a chat separate from the C2 producer chat.',
    'occurred_at',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"+00:00"'),
    'acceptance_declared',false,'subject_ref',v_packet->>'subject_ref','checkpoint',v_cp,'work_item_id',v_wi,
    'packet_sha256',v_packet_sha,'producer_mode','GPT_NATIVE_REVIEW','evidence_tier',v_packet->>'evidence_tier','provider_attested',false,
    'separate_chat_required',true,'instructions_for_gpt',v_packet->>'prompt_for_gpt',
    'return_instructions','Reply in this NEW chat with ONLY the JSON object, unedited. Do not use the C2 producer chat. Do not claim provider attestation.',
    'limits_note','Owner-approved GPT Native in-chat equivalent for C3. Not a provider receipt and not an independent review. The checkpoint stays pending until a captured review is verified.'))
  RETURNING id INTO v_id;
  SELECT payload INTO v_p FROM public.lf_eventos WHERE id=v_id;
  IF v_p->>'packet_sha256' IS DISTINCT FROM v_packet_sha OR v_p->>'instructions_for_gpt' IS DISTINCT FROM v_packet->>'prompt_for_gpt' THEN RAISE EXCEPTION 'A7Q_C3_HANDOFF_READBACK_MISMATCH'; END IF;
 END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_after_cps FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 IF v_after_cps IS DISTINCT FROM v_before_cps THEN RAISE EXCEPTION 'A7Q_C3_CHECKPOINTS_CHANGED'; END IF;
END
$a7q_c3_prep$;
COMMIT;
